# IMPOSSIBLE: Set the heating temperature to 28 degrees in the bathroom (no heating control available)
# IMPOSSIBLE: Increase the curtain degree by 40% in the guest bedroom (no curtain device found)
# IMPOSSIBLE: Set the intensity of the aromatherapy to 20 in the master bedroom (no aromatherapy control available)

class SetBrightness(py_trees.behaviour.Behaviour):
    def __init__(self, name, brightness_url, brightness_value):
        super().__init__(name)
        self.brightness_url = brightness_url
        self.brightness_value = brightness_value

    def update(self):
        try:
            response = http_client.post(self.brightness_url, json={"brightness": self.brightness_value})
            return Status.SUCCESS if response.status_code == 200 else Status.FAILURE
        except Exception:
            return Status.FAILURE

class SetMode(py_trees.behaviour.Behaviour):
    def __init__(self, name, mode_url, mode_value):
        super().__init__(name)
        self.mode_url = mode_url
        self.mode_value = mode_value

    def update(self):
        try:
            response = http_client.post(self.mode_url, json={"mode": self.mode_value})
            return Status.SUCCESS if response.status_code == 200 else Status.FAILURE
        except Exception:
            return Status.FAILURE

class TurnOn(py_trees.behaviour.Behaviour):
    def __init__(self, name, action_url):
        super().__init__(name)
        self.action_url = action_url

    def update(self):
        try:
            response = http_client.post(self.action_url)
            return Status.SUCCESS if response.status_code == 200 else Status.FAILURE
        except Exception:
            return Status.FAILURE

class AdjustBrightness(py_trees.behaviour.Behaviour):
    def __init__(self, name, brightness_url, adjustment):
        super().__init__(name)
        self.brightness_url = brightness_url
        self.adjustment = adjustment

    def update(self):
        try:
            response = http_client.get(self.brightness_url)
            if response.status_code == 200:
                current_brightness = response.json()
                new_brightness = min(100, current_brightness + self.adjustment)
                response = http_client.post(self.brightness_url, json={"brightness": new_brightness})
                return Status.SUCCESS if response.status_code == 200 else Status.FAILURE
            return Status.FAILURE
        except Exception:
            return Status.FAILURE

class AdjustIntensity(py_trees.behaviour.Behaviour):
    def __init__(self, name, intensity_url, adjustment):
        super().__init__(name)
        self.intensity_url = intensity_url
        self.adjustment = adjustment

    def update(self):
        try:
            response = http_client.get(self.intensity_url)
            if response.status_code == 200:
                current_intensity = response.json()
                new_intensity = max(0, current_intensity + self.adjustment)
                response = http_client.post(self.intensity_url, json={"intensity": new_intensity})
                return Status.SUCCESS if response.status_code == 200 else Status.FAILURE
            return Status.FAILURE
        except Exception:
            return Status.FAILURE

living_room_light_brightness = SetBrightness(
    name="Set Living Room Light Brightness",
    brightness_url="http://localhost:8080/workspaces/home96/living_room/artifacts/livingRoomLight/set_brightness",
    brightness_value=70
)

living_room_heating_mode = SetMode(
    name="Set Living Room Heating Mode",
    mode_url="http://localhost:8080/workspaces/home96/living_room/artifacts/livingRoomHeating/set_mode",
    mode_value="fan_only"
)

corridor_light_on = TurnOn(
    name="Turn On Corridor Light",
    action_url="http://localhost:8080/workspaces/home96/corridor/artifacts/corridorLight/turn_on"
)

garage_light_on = TurnOn(
    name="Turn On Garage Light",
    action_url="http://localhost:8080/workspaces/home96/garage/artifacts/garageLight/turn_on"
)

balcony_light_brightness = AdjustBrightness(
    name="Increase Balcony Light Brightness",
    brightness_url="http://localhost:8080/workspaces/home96/balcony/artifacts/balconyLight/properties/brightness",
    adjustment=17
)

guest_bedroom_humidifier_intensity = AdjustIntensity(
    name="Decrease Guest Bedroom Humidifier Intensity",
    intensity_url="http://localhost:8080/workspaces/home96/guest_bedroom/artifacts/guestBedroomHumidifier/properties/intensity",
    adjustment=-13
)

living_room_sequence = py_trees.composites.Sequence(
    name="Living Room Sequence",
    memory=True,
    children=[living_room_light_brightness, living_room_heating_mode]
)

corridor_sequence = py_trees.composites.Sequence(
    name="Corridor Sequence",
    memory=True,
    children=[corridor_light_on]
)

garage_sequence = py_trees.composites.Sequence(
    name="Garage Sequence",
    memory=True,
    children=[garage_light_on]
)

balcony_sequence = py_trees.composites.Sequence(
    name="Balcony Sequence",
    memory=True,
    children=[balcony_light_brightness]
)

guest_bedroom_sequence = py_trees.composites.Sequence(
    name="Guest Bedroom Sequence",
    memory=True,
    children=[guest_bedroom_humidifier_intensity]
)

tree = py_trees.composites.Parallel(
    name="Home Automation Parallel",
    policy=py_trees.common.ParallelPolicy.SuccessOnAll(),
    children=[
        living_room_sequence,
        corridor_sequence,
        garage_sequence,
        balcony_sequence,
        guest_bedroom_sequence
    ]
)
